using System.Collections;
using System.Collections.Generic;
using SuperTiled2Unity;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.Rendering.Universal;
using SoulRequiem.Core;

namespace SoulRequiem.Gameplay
{
    /// <summary>
    /// Owner of the map's mechanisms (Tiled "mechanics" layer, generated by Catalog/v2/maps/*.py). One per map scene.
    ///
    /// This component only:
    ///   1. reads the map: creates one <see cref="Mechanism"/> per object (kind by Type, see <see cref="MechanismRegistry"/>),
    ///      collects objects by name, "Light &lt;name&gt;" lights, hidden image palettes (glyphpal_*, picpal_*, pipepal_*) into <see cref="MechanismContext"/>;
    ///   2. every frame calls Animate / Tick and routes slashes, new flags and the T key to the right mechanism;
    ///   3. closes the centre-screen panel on Esc / walking away.
    /// The behaviour of each kind lives in its own class: Mechanics/Hazards, Mechanics/Effects, Mechanics/Puzzles.
    /// Note / lock / rose window panels: data in <see cref="MechanismPanels"/>, drawing in UI/MechanismPanelView.
    /// </summary>
    public partial class MapMechanics : MonoBehaviour
    {
        public static MapMechanics Instance { get; private set; }
        /// <summary>Standing at a console (camera panned away): PlayerController / PlayerCombat ignore input.</summary>
        public static bool ConsoleActive { get; internal set; }
        /// <summary>A reading / lock panel is open (Esc closes the panel instead of opening the Pause menu; left mouse does not slash).</summary>
        public static bool PanelOpen => MechanismPanels.BlocksInput;
        /// <summary>The panel closes by itself when the player walks farther than this from the mechanism area.</summary>
        public const float CloseRange = 1.1f;

        [Tooltip("Damage tick while standing in a spray / stinging zone (seconds)")]
        public float tick = 0.5f;

        private readonly List<Mechanism> mechs = new List<Mechanism>();
        private MechanismContext ctx;

        private void Awake()
        {
            Instance = this;
            ConsoleActive = false;
            MechanismPanels.Reset();
        }

        private void OnEnable() => PlayerCombat.Struck += OnStruck;

        private void OnDisable()
        {
            PlayerCombat.Struck -= OnStruck;
            ConsoleActive = false;
        }

        private void OnDestroy()
        {
            if (Instance == this) Instance = null;
            MechanismPanels.Reset();
        }

        private IEnumerator Start()
        {
            yield return null;                                  // wait for the Director to finish reading the map
            var dir = MapEncounterDirector.Instance;
            var pc = FindFirstObjectByType<PlayerController>();
            if (dir == null || dir.mapRoot == null || pc == null) { enabled = false; yield break; }
            ctx = new MechanismContext(this, dir, pc.transform, pc.GetComponent<Health>(), FindFirstObjectByType<CameraFollow>());

            ReadMap(dir.mapRoot);
            foreach (var m in mechs) m.Init();
            dir.Flags.Changed += _ => RefreshFlags();
            dir.Flags.Removed += _ => { foreach (var m in mechs) m.OnFlagsReset(); RefreshFlags(); };   // flag cleared -> the mechanism reopens
            RefreshFlags();
            foreach (var m in mechs) RegisterInteraction(m);
            Debug.Log($"[MapMechanics] {mechs.Count} mechanisms, {ctx.PipeSprites.Count} pipe sprites.");
        }

        // ------------------------------------------------------------------ reading the map
        /// <summary>Mechanism art layer: tile objects visible in Tiled, read like the "mechanics" layer.</summary>
        public const string ArtLayer = "mechanics_art";

        private void ReadMap(Transform mapRoot)
        {
            var pieces = new List<MechanismArt>();                 // `art_for` image pieces - attached to their mechanism after everything is read
            bool sawMechanicsLayer = false;
            foreach (var so in mapRoot.GetComponentsInChildren<SuperObject>(true))
            {
                string layer = so.transform.parent != null ? so.transform.parent.name : "";
                if (layer == "mechanics") sawMechanicsLayer = true;
                if (layer == "mechanics" || layer == ArtLayer)
                {
                    var art = MechanismArt.From(so);               // tile object -> image frame (turns off the image ST2U pre-built)
                    var props = so.GetComponent<SuperCustomProperties>();
                    if (art != null && props != null && props.GetString("art_for", "").Length > 0) { pieces.Add(art); continue; }
                    // mechanism areas are only position boxes - without unity:IsTrigger in Tiled, SuperTiled2Unity builds SOLID colliders
                    // (duo_arena covering the Warden Gallery floor became an invisible wall). Real colliders are made by each mechanism -> force every collider of this layer to be a trigger.
                    foreach (var c in so.GetComponentsInChildren<Collider2D>(true)) c.isTrigger = true;
                    var col = so.GetComponent<Collider2D>();
                    var rect = col != null ? new Rect(col.bounds.min, col.bounds.size)
                             : art != null ? art.Box
                             : new Rect(so.transform.position, Vector2.one * 0.3f);
                    var m = MechanismRegistry.Create(so.m_Type, so.m_TiledName);
                    m.Bind(so.m_Type, so.m_TiledName, rect, props, ctx);
                    m.AddArt(art);
                    mechs.Add(m);
                    ctx.All.Add(m);
                    continue;
                }
                string n = so.m_TiledName;
                if (string.IsNullOrEmpty(n)) continue;
                // hidden image palettes in the map: take the sprites, then disable the object
                if (TakePalette(so, n, "glyphpal_", s => { if (int.TryParse(n.Substring(9), out int d)) ctx.Glyphs[d] = s; })) continue;   // Vael glyphs
                if (TakePalette(so, n, "picpal_", s => ctx.Pictures[n.Substring(7)] = s)) continue;                                      // tranh
                if (TakePalette(so, n, "pipepal_", s => ctx.PipeSprites[n.Substring(8)] = s)) continue;                                  // pipe sprites
                if (!ctx.Named.TryGetValue(n, out var list)) ctx.Named[n] = list = new List<GameObject>();
                list.Add(so.gameObject);
            }
            foreach (var l in FindObjectsByType<Light2D>(FindObjectsInactive.Include, FindObjectsSortMode.None))
                if (l.name.StartsWith("Light ")) ctx.Lights[l.name.Substring(6)] = l;
            // a "mechanics" layer HIDDEN in Tiled (visible = 0) is skipped entirely by SuperTiled2Unity: every trap / light / mechanism disappears
            if (!sawMechanicsLayer && pieces.Count + mechs.Count > 0)
                Debug.LogError("[MapMechanics] No 'mechanics' layer found in the map - is it HIDDEN in Tiled? (show it again and save; to reduce clutter lower its opacity / lock it instead)");
            foreach (var a in pieces)
            {
                string owner = a.Props.GetString("art_for", "");
                var m = mechs.Find(x => x.Name == owner);
                if (m != null) m.AddArt(a);
                else Debug.LogWarning("[MapMechanics] image piece '" + a.Name + "': no mechanism named '" + owner + "' (art_for)");
            }
        }

        private static bool TakePalette(SuperObject so, string name, string prefix, System.Action<Sprite> store)
        {
            if (!name.StartsWith(prefix)) return false;
            var sr = so.GetComponentInChildren<SpriteRenderer>(true);
            if (sr != null) store(sr.sprite);
            so.gameObject.SetActive(false);
            return true;
        }

        private void RefreshFlags()
        {
            foreach (var m in mechs) m.OnFlagsChanged();
        }

        // ------------------------------------------------------------------ loop
        private void Update()
        {
            if (ctx == null) return;
            foreach (var m in mechs) m.Animate();
            if (ctx.ActiveConsole != null) { ctx.ActiveConsole.ControlUpdate(); return; }

            Vector2 p = ctx.Player.position;
            var open = MechanismPanels.Current;
            if (open != null)
            {
                var kb = Keyboard.current;
                if ((kb != null && kb.escapeKey.wasPressedThisFrame) || (open.Owner != null && !open.Owner.KeepPanelOpen(p)))
                    MechanismPanels.Close();
            }
            foreach (var m in mechs)
                if (!m.Done) m.Tick(p, m.Rect.Contains(p));
        }

        // ------------------------------------------------------------------ slashes / T key
        /// <summary>Radius of the hit being checked (slash ~0.45; Earthshatter 1.1) - objects needing a heavy hit (min_radius) read this value.</summary>
        public static float StrikeRadius { get; private set; }

        private void OnStruck(Vector2 c, float r)
        {
            if (ctx == null || ctx.ActiveConsole != null) return;
            StrikeRadius = r;
            // slashes only affect rusty valves and wooden barriers (bells / levers / dials / consoles use the T key)
            foreach (var m in mechs)
                if (!m.Done && m.ReactsToStrike && m.Overlaps(c, r)) m.OnStruck();
        }

        /// <summary>The HUD draws the key prompt at anchor + 0.18 and lifts it another ~46 px -> lower the anchor by 0.14 so the label bottom just touches the object top.</summary>
        internal const float PromptLift = 0.14f;

        private void RegisterInteraction(Mechanism m)
        {
            if (m.DefaultVerb == null) return;
            string verb = m.Props.GetString("verb", m.DefaultVerb);
            var r = m.Rect;
            bool reading = m.DefaultVerb == "Read" || m.DefaultVerb == "Examine";
            var anchor = new Vector2(r.center.x, Mathf.Min(r.yMax, r.center.y + 0.45f));
            // `prompt_at` = "x,y" (Tiled tile) = top middle of the opaque part of the object to read
            // (paper / book / board - not the bones or candles next to it). Precomputed from the image pixels by _tools/s399/prompt_at.py.
            string at = m.Props.GetString("prompt_at", "");
            if (at.Length > 0) anchor = (Vector2)ctx.TilePoint(at, anchor + Vector2.up * PromptLift) - Vector2.up * PromptLift;
            InteractionSystem.Add(new Interactable
            {
                id = m.Name, verb = verb, rect = r, clue = m.Clue,
                calmOnly = reading,                                                 // notes / puzzle boards are locked during combat
                range = m.Props.GetFloat("range", 0.55f),                          // e.g. a gate bolt: only reachable from the right side
                anchor = anchor,
                verbNow = () => m.PanelIsOpen ? "Close" : verb,
                available = () => m.Usable,
                use = () => { if (ctx.ActiveConsole == null) { SfxHooks.MechanismUsed(m); m.Use(); } },   // sound
            });
        }

        // ------------------------------------------------------------------ API for bosses / enemies
        /// <summary>Map object by Tiled name (e.g. morrow_pillar_0, isolde_coffin_1_open).</summary>
        public List<GameObject> Named(string name) => ctx != null ? ctx.NamedObjects(name) : new List<GameObject>();
        public void SetVisible(string names, bool on) => ctx?.Show(names, on);
        public Light2D LightNamed(string name) => ctx?.Light(name);

        /// <summary>The Ether Ram charging into a wall: rusty valves within radius r (Unity units) get their rust knocked off.
        /// (The Ram now uses the SluiceMechanism water valve; there are no ram pillars.)</summary>
        public bool RamImpact(Vector2 at, float r)
        {
            bool any = false;
            foreach (var m in mechs) if (m is ValveMechanism v && v.TryCrackRust(at, r)) any = true;
            if (any) Hints.Show("The ram's charge cracks the rust off a valve!", 2.5f);
            return any;
        }

        /// <summary>Centres of the Ichor pools of BROKEN glass tanks within radius r of `near` (where the toadlets rise).</summary>
        public System.Collections.Generic.List<Vector2> SpillPoints(Vector2 near, float r)
        {
            var list = new System.Collections.Generic.List<Vector2>();
            foreach (var m in mechs)
                if (m is TankMechanism t && t.Done)
                {
                    var p = t.SpillPoint;
                    if ((p - near).sqrMagnitude <= r * r) list.Add(p);
                }
            return list;
        }

        /// <summary>The Gorgemaw toad slams down: glass tanks within radius r break. Returns true if any tank broke (the toad is stunned).</summary>
        public bool Shatter(Vector2 at, float r)
        {
            bool any = false;
            foreach (var m in mechs) if (m is TankMechanism t && t.TryShatter(at, r)) any = true;
            return any;
        }
    }
}
